head.script:
scwin.screenId = "jldfil05028";

///////// 1. 변수 및 선언 영역 /////////

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).
scwin.LD_MKT_TP_CD = '1';

scwin.CD_ADDLST = '005';

scwin.BZ_ADDPRE = 2;

scwin.BZ_ADDLST = 3;

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  2); } }, { id: "btn_ElwSub", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ==  1); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_fbzNetcap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "fbzNetcap")); } },
        { childId: "ipt_eqtycap", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "eqtycap")); } },
        { childId: "ipt_totRiskAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totRiskAmt")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_reqPersisPrincCapVal", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "reqPersisPrincCapVal")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent("dma_RegisterReq").set("bzCd", scwin.BZ_ADDLST);
        $c.util.getComponent("dma_RegisterReq").set("listBzTpCd", scwin.CD_ADDLST);
        $c.util.getComponent("dma_RegisterReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        /* 수동 전환 필요: transTbl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        /* 수동 전환 필요: transTbl[1].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        scwin.calNetRto();
        scwin.calOtcRto();
        scwin.commaValueAll();
        await (async () => { const m = $c.util.getComponent("dma_readDataVO"); const v = (m && m.get) ? m.get("resultMsg") : ""; if (v) { await $c.win.alert(String(v)); } })();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05028.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05028.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

