/**
 * @method
 * @name scwin.calNetRto
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calNetRto = function () {
    /* sdd-asis-lifecycle:begin fn_CalNetRto — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_fbzNetcap').getValue() == null ? '' : String($c.util.getComponent('ipt_fbzNetcap').getValue())) !== '' && ($c.util.getComponent('ipt_totRiskAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_totRiskAmt').getValue())) !== '' && ($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue() == null ? '' : String($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) !== '') {
        $c.util.getComponent('ipt_netRto').setValue(Math.round(((scwin.rmComma($c.util.getComponent('ipt_fbzNetcap').getValue()) - scwin.rmComma($c.util.getComponent('ipt_totRiskAmt').getValue())) / scwin.rmComma($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) * 10000) / 100);
    }
    /* sdd-asis-lifecycle:end */
};


